#nullable enable // autogenerated

using MVZ2.Vanilla.Entities;
using MVZ2Logic.Entities;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Enemies
{
    /// <summary>
    /// 撑杆跳僵尸的状态行为：
    /// 撞到器械且手上还有撑杆时不啃食，改为跳跃状态（跳过它）；
    /// 跳跃过程中保持跳跃状态直到落地（此时原版走路速度不会干扰抛物线）；
    /// 没有撑杆时和普通僵尸一样走路/啃食；死亡交给原版逻辑。
    /// </summary>
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.poleVaultingZombie_State)]
    public class PoleVaultingZombie_StateBehaviour : EnemyStateBehaviour
    {
        public PoleVaultingZombie_StateBehaviour(string nsp, string name) : base(nsp, name)
        {
        }
        protected override int GetActiveState(Entity enemy)
        {
            // 跳跃中：保持跳跃状态（走路速度不会干扰抛物线）
            if (PoleVaultingZombie.IsJumping(enemy))
                return PoleVaultingZombie.STATE_JUMP;
            // 有撑杆且撞到器械：改为跳跃（而不是啃食）
            if (PoleVaultingZombie.ShouldJump(enemy))
                return PoleVaultingZombie.STATE_JUMP;
            return base.GetActiveState(enemy);
        }
    }
}
